from pathlib import Path
import json,math,hashlib

def build_direct_three_widget(H):
 O=H/'直达ILZ紧邻三障碍展示_v0.1_20261024';raw=(O/'worlds.json').read_bytes();W=json.loads(raw);audit=json.loads((O/'independent_verify.json').read_text('utf-8'));assert audit['passed'] and audit['worlds_sha256']==hashlib.sha256(raw).hexdigest()
 worlds=[];excluded=[]
 for w in W:
  if w['status']!='complete':
   excluded.append(w['name']+'：'+','.join(a['view']+'仅取得'+str(len(a['events']))+'次障碍' for a in w['agents'] if a['status']!='complete'));continue
  ini=w['initial'];cards=[]
  for a in w['agents']:
   cum=[0.]
   for x,y in zip(a['full_path'],a['full_path'][1:]):cum.append(cum[-1]+math.dist(x,y))
   cards.append(dict(view=a['view'],path=a['full_path'],cum=cum,length=a['length'],seconds=a['seconds'],credits=a['credits'],expected=len(a['final_H']),events=a['events'],phases=a['phases'],return_length=a['return_length'],inspection_length=a['inspection_length']))
  worlds.append(dict(name=w['name'],size=w['size'],family=w['family'],free=ini['free'],targets=ini['published_targets'],history=[],base=ini['base'],current=ini['base'],cards=cards))
 data=json.dumps(worlds,ensure_ascii=False,separators=(',',':'));(H/'直达ILZ三障碍回放数据.json').write_text(data,encoding='utf-8')
 markup="""<div id="direct-replay" class="replay"><h4>从待检区入口起飞：I／L／Z形区域，三次紧邻前方障碍</h4><p>任务初始化为待检，从区域入口格起飞并采集起点，最后返回这里。各自达到20%、50%、75%覆盖进度后，在即将进入的紧邻未飞格公开障碍，旧计划的下一段立即受阻，停在安全格心重规划。</p><p class="small muted">预定9组地图；8组完成三障碍四图比较。小I图的PPCPP＋直达未取得第三次合格紧邻阻断，单列不适用，未更换地图或伪造第三障碍。</p><div class="dr-controls"><label>完整案例 <select id="dr-case"></select></label><button id="dr-play">▶ 同步播放</button><button id="dr-reset">重置</button><label>跳到 <select id="dr-event"><option value="0">障碍1 · 20%</option><option value="1">障碍2 · 50%</option><option value="2">障碍3 · 75%</option></select></label><button id="dr-return">看障碍出现</button><button id="dr-end">看完整路线</button><label>速度 <select id="dr-speed"><option value="4">4 米/秒</option><option value="12" selected>12 米/秒</option><option value="30">30 米/秒</option></select></label></div><input id="dr-slider" type="range" min="0" max="1000" value="0" aria-label="同步距离"><p id="dr-info"></p><div id="dr-grid"></div><div id="dr-result" class="note"></div><p class="small muted">黄色＝待检，绿色＝按中心有效区取得信用；红色＝已经公开的障碍，禁止进入且目标暂缓。蓝点＝起降点，橙点＝无人机；绿色斜线凸显直飞。灰色虚线为当前最近一次事件前的旧计划，淡蓝色为当前新计划。四图同速，但事件按各自进度触发，时间和坐标可不同。</p><details><summary>实验边界与不适用案例</summary><p>预定小中大×I/L/Z九图，固定seed20261020。区域为原始存档任务格，不按收益筛选。首次规划两方法各一次，原生/直达共享；之后每视图按各自真实历史独立重算，冻结核心、直达、覆盖判据均不改。时间显示起飞＋三次重规划的共同端到端累计，原生不计离线诊断的未采用直达计算。</p><p>障碍是下一段马上进入的相邻格，而非下一远处锚点；轴向为四邻格，恰沿45°穿过角点时为对角相邻格。此前不得穿过障碍格，剩余任务与基地必须可达。当前入口要求实际轴向来向，因此仅在自然满足该条件的格心公开；如阈值时无资格，沿原计划到首次合格位置，不伪造来向、不强制补飞、不宣称任意非格心探测。实际触发比例和等待距离逐项展示。</p><p>覆盖率分母为当前公开可检任务（已遮挡任务暂缓），不是相同墙钟时刻。由于各自障碍坐标可能不同，这里是同一事件规则下的完整响应展示，不是同一障碍地图的严格因果配对；距离和计算时间差不能全部归因于直达。</p><p>未满足三次紧邻阻断的预定案例：EXCLUDED。未换图、未放宽成远处障碍；其已保存调用全部保留，不混入完整四图比较。部分会话的未完成汇总字段不用于路线总账。</p></details></div>""".replace('EXCLUDED','；'.join(excluded) if excluded else '无')
 css='#direct-replay{margin:24px 0;padding:20px;border:1px solid #c9d9e6;background:#f6f9fc;border-radius:10px}#direct-replay h4{font-size:20px;margin:0 0 10px}.dr-controls{display:flex;flex-wrap:wrap;gap:9px;align-items:center}.dr-controls select,.dr-controls button{max-width:100%;padding:8px;border:1px solid #bdcddd;border-radius:5px;background:white;color:#203047}#dr-slider{width:100%;margin:16px 0 0}#dr-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.dr-card{background:white;border:1px solid #cedce7;border-radius:8px;padding:12px;min-width:0}.dr-card h5{font-size:17px;margin:0 0 8px}.dr-card canvas{display:block;width:100%;aspect-ratio:1.35;background:#fff}.dr-card .dr-stat{font-size:13px;line-height:1.8}.dr-card b{color:#245c96}.dr-bar{height:5px;background:#e5edf4;margin:6px 0}.dr-bar i{display:block;height:100%;background:#5391bc}#dr-result{font-size:14px}#dr-info{font-size:13px}@media(max-width:650px){#direct-replay{padding:10px}#dr-grid{grid-template-columns:1fr}.dr-controls label{max-width:100%}.dr-controls select{width:100%}}'
 js='(()=>{const W='+data+';'+(H/'direct_three_replay.js').read_text('utf-8')+'})();'
 return markup,css,js
